using System.Collections.Generic;
using HarmonyLib;
using UnityEngine;

namespace LethalMinecraft
{
    /// <summary>
    /// The Nether is generated by its own DunGen generator, and other mods treat every DungeonGenerator.Generate as the
    /// day's facility (#108). LethalLevelLoader's prefix renumbers every entrance in the scene, the facility's inside
    /// doors too, so the main door's two halves stopped matching: "The entrance appears to be blocked." It also logged a
    /// new day, changed the fire exit count and moved the moon's out-of-bounds triggers.
    /// - While the Nether generates, LethalLevelLoader's prefix is skipped (patched when it's loaded; nothing otherwise).
    /// - Whatever else runs, every entrance gets its id back afterwards.
    /// </summary>
    public static class NetherGenGuard
    {
        public static bool Generating;
        public static int Restored, SkippedLll; // (dev/tests)
        static bool patched;

        static void PatchLll()
        {
            if (patched) return;
            patched = true;
            var m = AccessTools.Method("LethalLevelLoader.Patches:DungeonGeneratorGenerate_Prefix");
            if (m == null) return;
            new Harmony(Plugin.Guid + ".nethergen").Patch(m, prefix: new HarmonyMethod(typeof(NetherGenGuard), nameof(SkipWhileNether)));
            Plugin.Log.LogInfo("LethalLevelLoader found: its dungeon preparation is skipped while the Nether generates");
        }

        static bool SkipWhileNether()
        {
            if (!Generating) return true;
            SkippedLll++;
            return false;
        }

        /// <summary>Runs <paramref name="generate"/> (the Nether's DunGen call) with the facility's entrances kept as they are.</summary>
        public static void Run(System.Action generate)
        {
            PatchLll();
            var ids = new List<(EntranceTeleport e, int id)>();
            foreach (var e in Object.FindObjectsOfType<EntranceTeleport>()) ids.Add((e, e.entranceId));
            Generating = true;
            try { generate(); }
            finally
            {
                Generating = false;
                foreach (var (e, id) in ids)
                    if (e != null && e.entranceId != id) { e.entranceId = id; e.exitScript = null; Restored++; }
            }
        }

        public static string Describe() => $"skippedLll={SkippedLll} restored={Restored} lllPatched={patched}";
    }
}
